class Random {
private:
    uint32_t seed_;

public:
    explicit Random(uint32_t s) : seed_(s & 0x7fffffffu) {}

    uint32_t Next() {
        // Linear congruential generator
        seed_ = seed_ * 16807 % 2147483647;
        return seed_;
    }

    uint32_t Uniform(int n) {
        return Next() % n;
    }

    bool OneIn(int n) {
        return Uniform(n) == 0;
    }
};

Random r(12345);
bool result = r.OneIn(5);
